class ResourceHandle {
private:
    int descriptor;
    bool isActive;

public:
    // Proper initialization using initializer list
    ResourceHandle(int fd, bool status)
    : descriptor(fd), isActive(status)
    {}

    // Ensures default objects are also consistently initialized
    ResourceHandle()
    : ResourceHandle(-1, false) // Constructor delegation (C++11+)
    {}

    // Note: Members remain private, enforcing encapsulation
};
